    cancelNoteTool();closeCommandPalette();project=emptyProject();project.bpm=120;project.songMode=true;project.loop=false;currentFile=File();selectedTrack=7;selectedNote=0;selectedNotes={0};selectedClip=0;undoStack.clear();redoStack.clear();clipboardHasClip=false;dirty=false;
